const basePremiumOf = (item: Item): number => 100;

const quotePremium = (items: Item[]): number => {
  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const premiumBeforeFee = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
  return roundUpToWholeG(premiumBeforeFee + PROCESSING_FEE);
};
